while true; do
  resp=$(curl -sS -H "Authorization: token $GH_TOKEN" -H "Accept: application/vnd.github+json" \
    "https://api.github.com/repos/missingbulb/NoRFinder/commits/02ced7756b79b9b18608f6c1ec85920a2dd17a45/check-runs" || true)
  status=$(echo "$resp" | node -e '
    let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
      try{const j=JSON.parse(d);
        for(const r of j.check_runs||[]) console.log(r.name+": status="+r.status+" conclusion="+r.conclusion);
      }catch(e){console.log("parse-error");}
    });')
  echo "$status"
  if ! echo "$status" | grep -q "status=in_progress\|status=queued"; then
    echo "ALL-CONCLUDED"
    break
  fi
  sleep 30
done

